from typing import Dict, List

def topo_sort_tasks(deps: Dict[str, List[str]]) -> List[str]:
    """
    Returns a valid topological execution order for tasks.

    :param deps: A dictionary where deps[task] lists the prerequisites that must run BEFORE task.
    :return: A list of task names in a valid topological execution order. If a cycle exists, returns an empty list.
    """
    in_degree = {task: 0 for task in deps}
    for task in deps:
        for dep in deps[task]:
            in_degree[dep] += 1

    queue = [task for task in in_degree if in_degree[task] == 0]
    queue.sort()  # Sort tasks with no prerequisites lexicographically

    result = []
    while queue:
        task = queue.pop(0)
        result.append(task)
        for dependent_task in deps:
            if task in deps[dependent_task]:
                in_degree[dependent_task] -= 1
                if in_degree[dependent_task] == 0:
                    queue.append(dependent_task)
                    queue.sort()  # Sort tasks with no prerequisites lexicographically

    if len(result) != len(deps):
        return []  # Cycle exists

    return result
