from collections import OrderedDict

def simulate_lru(capacity: int, ops: list[tuple]) -> list[int]:
    cache = OrderedDict()
    results = []

    for op, key, value in ops:
        if op == 'put':
            if key in cache:
                del cache[key]
            elif len(cache) == capacity:
                cache.popitem(last=False)
            cache[key] = value
        elif op == 'get':
            if key in cache:
                results.append(cache[key])
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

def flatten_json(obj: dict, sep: str = '.') -> dict:
    """
    Recursively flattens nested dictionaries into a single-level dictionary.

    Args:
    obj (dict): The dictionary to be flattened.
    sep (str): The separator to join keys. Defaults to '.'.

    Returns:
    dict: The flattened dictionary.
    """
    def helper(obj: dict, prefix: str = '') -> dict:
        result = {}
        for key, value in obj.items():
            new_key = prefix + key if prefix else key
            if isinstance(value, dict):
                result.update(helper(value, new_key + sep))
            else:
                result[new_key] = value
        return result

    return helper(obj)

