from typing import Dict, List, Tuple

def is_balanced_brackets(s: str) -> bool:
    """
    Checks whether all brackets in string s are properly balanced and nested.

    Args:
    s (str): The input string to check.

    Returns:
    bool: True if all brackets are balanced and nested, False otherwise.
    """
    stack: List[Tuple[str, int]] = []
    bracket_map: Dict[str, str] = {')': '(', '}': '{', ']': '['}
    for i, char in enumerate(s):
        if char in bracket_map.values():
            # Opening bracket, push onto stack
            stack.append((char, i))
        elif char in bracket_map.keys():
            # Closing bracket, check if stack is empty or top of stack doesn't match
            if not stack or stack.pop()[0] != bracket_map[char]:
                return False
    # If stack is empty after processing entire string, all brackets are balanced
    return not stack


